package io.knowledgebrain.gateway;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
class GitHubLearningProxyTest {GatewayProxyTest f;String id="019a0000-0000-7000-8000-000000000001",base="/api/spaces/"+id,root=base+"/roadmaps/"+id+"/github-evidence";@BeforeEach void setup()throws Exception{f=new GatewayProxyTest();f.prepare();}@AfterEach void clean(){f.stop();}
 @Test void privateCatalogRelatedAndRevisionQueriesAreStrictBeforeTransport()throws Exception{var valid=f.request("GET",root);valid.setQueryString("state=RETIRED&limit=20&after="+id);assertEquals(200,f.gateway.proxy(valid).getStatusCode().value());var related=f.request("GET",base+"/github-learning-evidence");related.setQueryString("repositoryId="+id+"&commitId="+id+"&state=ACTIVE&limit=20");assertEquals(200,f.gateway.proxy(related).getStatusCode().value());for(String query:java.util.List.of("state=PUBLIC","actorId="+id,"state=ACTIVE&state=RETIRED","limit=101","after=invalid","limit=20&","before=1")){var r=f.request("GET",root);r.setQueryString(query);assertThrows(ResponseStatusException.class,()->f.gateway.proxy(r));}var history=f.request("GET",root+"/"+id+"/revisions");history.setQueryString("before=9223372036854775808");assertThrows(ResponseStatusException.class,()->f.gateway.proxy(history));assertEquals(2,f.requests.get());}
 @Test void opaqueCreateKeyCasAndBodylessReadsRetainGatewayGuards()throws Exception{var post=f.request("POST",root);post.addHeader("Origin","https://localhost:8443");post.setContentType("application/json");post.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->f.gateway.proxy(post));post.addHeader("Idempotency-Key","a".repeat(32));assertEquals(200,f.gateway.proxy(post).getStatusCode().value());assertEquals("a".repeat(32),f.headers.get().getFirst("Idempotency-Key"));var body=f.request("GET",root);body.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->f.gateway.proxy(body));var remove=f.request("DELETE",root+"/"+id);remove.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->f.gateway.proxy(remove));assertEquals(1,f.requests.get());}
}
